const tradingResolvers = {
  Subscription: {
    portfolioValuationLive: {
      subscribe: async (parent, args, context) => {
        if (!context.user) throw new Error('Authentication required');
        const portfolio = await Portfolio.findOne({ where: { id: args.portfolioId, ownerId: context.user.id } });
        if (!portfolio) throw new Error('Access denied to portfolio stream');
        return redisPubSub.asyncIterator([`PORTFOLIO_${args.portfolioId}_VALUATION`]);
      },
      resolve: (payload) => payload.currentEquity
    }
  }
};
